{
  "indicator": "window_mean",
  "baseline_window": "baseline",
  "window_rule": "mean(window)>mean(baseline)+4",
  "ddof": 0,
  "owner": "order_oncall",
  "response": "investigate_window",
  "expected_replays": {
    "normal": false,
    "boundary": false,
    "breached": true
  }
}

{
  "permitted_responses": [
    "data_repair",
    "approved_rollback",
    "gated_retraining"
  ],
  "selected_fixture_authorization": "approved rollback cfg.bad -> cfg.r1 under lab.operator; readiness and bounded prediction gates required",
  "quality_denominator": "matched_eligible_labels; zero means undefined",
  "hypothesis": "configuration mismatch, distinguished by approved-configuration replay"
}

{
  "PipelineName": "order-retrain-lab",
  "snapshot_file": "assets/snapshot.g1.json",
  "approved_generation": "1",
  "approved_sha256": "b8485b1fcdc8e30ece97590d5d299807d77a48136e1eda6995f4bc0280183b66",
  "ClientRequestToken": "token.accept",
  "trigger_topic": "lab-approved-events",
  "filter": "authorized=true AND snapshot_ref=snapshot.g1",
  "build_identity": "lab.runner",
  "secret_version_reference": "projects/order-lab/secrets/execution-client/versions/1",
  "secretEnv": [
    "EXECUTION_CLIENT"
  ],
  "stage_contract": "entry -> verify_snapshot -> function_test -> execute -> inspect_consumed_input; each waitFor dependency required and failure fatal",
  "PipelineParameters": [
    {
      "Name": "SnapshotRef",
      "Value": "snapshot.g1"
    },
    {
      "Name": "Generation",
      "Value": "1"
    }
  ]
}

{
  "required_fields": [
    "steps",
    "availableSecrets"
  ],
  "safe_roundtrip_required": true,
  "failure_policy": "required gates fatal"
}

{
  "steps": [
    {
      "id": "entry",
      "name": "python:3.11",
      "args": [
        "python3",
        "entry_fixture.py"
      ]
    },
    {
      "id": "function_test",
      "name": "python:3.11",
      "waitFor": [
        "entry"
      ],
      "args": [
        "python3",
        "learner.py"
      ]
    },
    {
      "id": "execute",
      "name": "python:3.11",
      "waitFor": [
        "function_test"
      ],
      "args": [
        "python3",
        "execution_fixture.py"
      ]
    }
  ]
}

{
  "event": {
    "run_key": "K",
    "pipeline": "order-retrain-lab"
  },
  "busy_policy": "defer",
  "coordinator_contract": {
    "atomic_admit(run_key,pipeline)": "Atomically reserve unique run key AND pipeline slot and persist job_id. Return accepted, duplicate or busy plus persisted identity; durable coordinator is external to learner process.",
    "inspect(run_key)": "Read durable record; completed records retained.",
    "confirm_terminal_and_release(run_key,job_id)": "Release active slot only after executor confirms terminal; retain completed key."
  },
  "executor_contract": {
    "launch(job_id)": "Idempotent executor token; at most one logical job per job_id. Unknown response must be reconciled with same token.",
    "attach(job_id)": "Resume or reconcile existing identity.",
    "status(job_id)": "Return running or confirmed terminal."
  },
  "test_scenarios": [
    "concurrent_same_key",
    "concurrent_different_key",
    "restart_after_reservation",
    "restart_after_launch",
    "unknown_launch_response",
    "completed_duplicate"
  ],
  "fatal_dependencies": [
    "admission",
    "function_test",
    "execute"
  ]
}

{
  "required_fields": [
    "steps"
  ],
  "safe_roundtrip_required": true,
