        "function_test"
      ],
      "args": [
        "python3",
        "execution_fixture.py"
      ]
    }
  ]
}

{
  "INSTANCE": "serving-lab",
  "ZONE": "lab-zone-a",
  "authorized_identity": "lab.operator",
  "allowed_actions": [
    "inspect",
    "reproduce_fault",
    "test_hypothesis",
    "stop",
    "wait_stopped",
    "start",
    "wait_running",
    "reconnect",
    "readiness",
